// Copy for the Guide page (GettingStarted.svelte): task topics with numbered steps and screenshots, plus the
// Concepts reference and the keyboard shortcuts. Text follows the Google developer documentation style: second
// person, active voice, one action per step, UI names in bold exactly as on screen.
//
// Inline markup in step text and summaries (see guideInline.ts): **bold** for UI names and [label](#/guide#topic)
// for a link to another topic. Images live in web/src/assets/guide/ and are generated by scripts/guide-shots.ts,
// which captures exactly the keys listed here.

export interface GuideImage {
  /** File name without extension: web/src/assets/guide/<key>.webp. */
  key: string;
  /** Describes what the image highlights; the step text also stands on its own without the image. */
  alt: string;
}

export interface GuideStep {
  /** The step's lead-in. With `subs`, it introduces them and reads on its own. */
  text: string;
  /**
   * Sub-steps, one per highlighted control, in reading order. Rendered as "2.1", "2.2", ... under the step, and the
   * image's badges carry the same labels. Needs at least two. A step with one highlight has no `subs`.
   */
  subs?: string[];
  /** Text after the sub-steps. */
  after?: string;
  image?: GuideImage;
}

export interface GuideTask {
  id: string;
  title: string;
  /** One sentence on what the reader will get done. */
  summary: string;
  steps: GuideStep[];
  /** What the reader has when the steps are done, and where the task continues. */
  next?: string;
}

const img = (key: string, alt: string): GuideImage => ({ key, alt });

